// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guess, uint256 lockBlockOffset) public {
        // Keep the domain wide but ensure block arithmetic is well-defined.
        uint256 offset = bound(lockBlockOffset, 1, 1000);

        address player = address(0xBEEF);
        vm.deal(player, 2 ether);

        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);

        // Move to a block strictly after the recorded guess block.
        vm.roll(block.number + offset + 1);

        uint256 balBefore = player.balance;

        bool ok;
        vm.prank(player);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = player.balance;
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(block.number - offset - 1)));
        bool guessWasCorrect = (guess == expectedAnswer);

        if (ok) {
            assertEq(balAfter - balBefore == 2 ether, guessWasCorrect);
        } else {
            assertTrue(balAfter == balBefore);
        }
    }
}
